drills.solution:
export function pick(obj, keys) {
  const out = {};
  for (const k of keys) if (Object.hasOwn(obj, k)) out[k] = obj[k];
  return out;
}

export function omit(obj, keys) {
  const drop = new Set(keys);
  const out = {};
  for (const k of Object.keys(obj)) if (!drop.has(k)) out[k] = obj[k];
  return out;
}

tests.code:
const proto = { role: 'admin' };
const user = Object.create(proto);
user.id = '1';
assert.deepEqual(mod.pick(user, ['id', 'role']), { id: '1' });
assert.deepEqual(mod.omit(user, []), { id: '1' });

const u = { id: '1', secret: 's' };
const a = mod.omit(u, ['secret']);
const b = mod.pick(u, ['id']);
assert.deepEqual(u, { id: '1', secret: 's' });
assert.notEqual(a, u);
assert.notEqual(b, u);

drills.explanation:
`pick` walks the requested keys and checks ownership; `omit` walks the object's own keys and skips a Set of excluded names:

```js
export function omit(obj, keys) {
  const drop = new Set(keys);
  const out = {};
  for (const k of Object.keys(obj)) if (!drop.has(k)) out[k] = obj[k];
  return out;
}
```

Using `k in obj` in `pick` would copy the inherited `role`; writing `out[k] = obj[k]` for every listed key would create `email: undefined`, which serialises differently in some clients and breaks key-based checks.
